        check (msg, t.b2d.rank == 2 && (int)t.b2d.dims[0] == m
                        && (int)t.b2d.dims[1] == n && (int)t.b2d.size == N);
        snprintf (msg, sizeof msg,
                  "n=%d m=%d B[r,c] == c*100+r for every element", n, m);
